Section M2A.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (m : amem) (WK DT mtl nbS tl : Z) (ws rank : list Z) (js jt : list byte).
  Variables (rs rs2 : list Z) (syms : list (option Z)) (cells : list (option deltX1)).
  Variable Q : machine_state -> Prop.
  Notation HW := (WK + 1236).
  Notation SY := (WK + 980).
  Notation RS := (WK + 52).
  Notation NC := (Z.to_nat (2^(mtl + 1))).
  Notation DTE := (DT + 4 + 2 * 2^(mtl + 1)).
  Hypothesis HMTL : 1 <= mtl <= 12.
  Hypothesis HTL : 1 <= tl <= mtl + 1.
  Hypothesis HTL12 : tl <= 12.
  Hypothesis WFW : WF ws rank nbS tl.
  Hypothesis LJS : length js = 256%nat.
  Hypothesis LJT : length jt = (2 * NC)%nat.
  Hypothesis RSL : rank_start_loop (Z.to_nat (tl + 1)) 0 0 rank (repeat 0 13) = Ok rs.
  Hypothesis SOL : sort_loop (Z.to_nat nbS) 0 ws rs (repeat None 256) = Ok (rs2, syms).
  Hypothesis FWL : fill_weights (Z.to_nat tl) 1 tl rank syms (repeat None NC) (Znth 0 rank) 0 = Ok cells.
  Hypothesis HDT : ablk DT DTE.
  Hypothesis DT8 : DT mod 8 = 0.
  Hypothesis HWK : ablk WK (WK + 1492).
  Hypothesis DJW : DTE <= WK \/ WK + 1492 <= DT.
  Hypothesis DSP : DTE <= SPA.
  Hypothesis WSP : WK + 1492 <= SPA.
  Hypothesis KSP : KHIGH <= SPA.
  Hypothesis SP47 : SPA + 312 <= 2^47.
  Hypothesis UDT : unpoisoned m DT DTE.
  Hypothesis ZW : zshadow m WK 1492.
  Hypothesis RDT : rng RNG DT (DTE - DT).
